export function fishSvg(f,unknown=false){const id='f'+Math.random().toString(36).slice(2,9),c=unknown?'#6d8680':f.color,fin=unknown?'#6d8680':f.fin;const h=f.shape==='disc'?34:f.shape==='angel'?29:['slim','trout','arowana','eel','dragon'].includes(f.shape)?16:f.shape==='catfish'?18:24;return `<svg class="fish-art" viewBox="0 0 190 100" role="img" aria-label="${unknown?'Undiscovered fish':f.name}"><defs><linearGradient id="${id}" x1="0" y1="0" x2="0.2" y2="1"><stop stop-color="#f4e9ca"/><stop offset=".4" stop-color="${c}"/><stop offset="1" stop-color="${fin}"/></linearGradient></defs><g transform="translate(95 50)"><path d="M-35 0 L-72 -${h+(['betta','fancy','guppy'].includes(f.shape)?20:7)} Q-${f.shape==='betta'?90:63} 0 -72 ${h+(['betta','fancy','guppy'].includes(f.shape)?20:7)} Z" fill="${fin}"/><path d="M-20 -${h-3} L-6 -${h+15} L23 -${h-5} M-18 ${h-4}L-5 ${h+12}L22 ${h-7}" fill="${fin}" opacity=".85"/><ellipse rx="49" ry="${h}" fill="url(#${id})"/><path d="M-4 3 Q-24 28 -27 9" fill="${fin}" opacity=".75"/>${f.shape==='koi'?'<ellipse cx="-20" cy="-3" rx="12" ry="14" fill="#c7805c" opacity=".9"/><ellipse cx="14" cy="-11" rx="10" ry="9" fill="#c7805c"/>':''}${f.id==='perch'||f.id==='discus'?[-25,-11,3,17].map(x=>`<path d="M${x} -${h-3}q-7 ${h} 0 ${h*2-6}" stroke="${fin}" stroke-width="3" fill="none" opacity=".6"/>`).join(''):''}<path d="M27 -${h*.6}Q18 0 27 ${h*.6}" stroke="${fin}" stroke-width="1" fill="none" opacity=".8"/>${unknown?'<text x="0" y="8" text-anchor="middle" fill="#b9c8be" font-family="Georgia" font-size="25">?</text>':'<circle cx="32" cy="-5" r="6" fill="#f4e5c7"/><circle cx="33" cy="-5" r="3.6" fill="#1b363b"/><circle cx="34" cy="-6" r="1.1" fill="#fff"/>'}</g></svg>`;}
